// CMOUOpen opens a live [CMOUStream] on a warm-up history, oldest bar first,
// and returns it with its value at the last history bar, the value [Core.CMOU]
// writes there.
//
// inReal is the history; the parameters are those of [Core.CMOU].
//
// The error is [InsufficientHistory] for a history of at most
// [Core.CMOULookback] bars, and [BadParam] for a parameter out of range.
func (c *Core) CMOUOpen(inReal []float64, optInTimePeriod int) (*CMOUStream, float64, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, 0, BadParam
	}
	sp, err := c.cmouOpenInternal(inReal, 0, int32(optInTimePeriod))
	if err != nil {
		return nil, 0, err
	}
	return sp, sp.cur_outReal, nil
}

// CMOUOpenAndFill opens a stream as [Core.CMOUOpen] does and also writes the
// outputs over the whole history, as [Core.CMOU] writes them for bars 0 through
// len(inReal)-1, returning that range.
//
// Each output must hold len(inReal) minus [Core.CMOULookback] values and share
// no memory with an input or another output.
//
// The errors are those of [Core.CMOUOpen], and [BadParam] for an output that is
// empty, too short or sharing memory.
func (c *Core) CMOUOpenAndFill(inReal []float64, optInTimePeriod int, outReal []float64) (*CMOUStream, OutRange, error) {
	if !fitsInt32(optInTimePeriod) {
		return nil, OutRange{}, BadParam
	}
	if len(inReal) > IndexMax+1 {
		return nil, OutRange{}, OutOfRangeEndIndex
	}
	lookback := int(c.cmouLookback(int32(optInTimePeriod)))
	if lookback < 0 {
		return nil, OutRange{}, BadParam
	}
	outLen := max(len(inReal)-lookback, 0)
	if len(outReal) == 0 || len(outReal) < outLen {
		return nil, OutRange{}, BadParam
	}
	if sameStart(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	if outLen > 0 && overlaps(outReal, inReal) {
		return nil, OutRange{}, BadParam
	}
	var outBegIdx, outNBElement int32
	sp, err := c.cmouOpenAndFillInternal(inReal, 0, int32(optInTimePeriod), &outBegIdx, &outNBElement, outReal)
	if err != nil {
		return nil, OutRange{}, err
	}
	return sp, OutRange{BegIdx: int(outBegIdx), NBElement: int(outNBElement)}, nil
}
